test "R32 launch records fit every served SM without qualifying unmeasured compiler versions" {
    try std.testing.expectEqual(@as(usize, 60), records.len);
    try std.testing.expectEqual(@as(usize, 0), try registry.checkCuda(std.testing.allocator, &records, true));
    for (records) |r| try std.testing.expectEqual(registry.none, registry.usageFor(r, .{ .major = 13, .minor = 3 }));
}
